  _ = `Börja skriva för att få en filtrerad lista av dina paket.`,
  _ = `Observera att de här inte är app-ID:n. De är butikspaket som säljer din produkt i Steam-butiken.`,
  _ = `Ange paketnamn eller -ID här`,
  _ = `Välj ett eller flera paket nedan och klicka på Fortsätt för att lägga till dem till denna bunt.`,
  _ = `Buntsamarbete`,
  _ = `Valfritt: Du kan välja att bjuda in andra utvecklare till att inkludera sina spel i din bunt. Som ägare av bunten, är det ditt ansvar att att samordna med andra utvecklare. Som ägare är du också den enda som kan publicera bunten i Steam-butiken. De inbjudna parterna kan välja vilka spel/paket som ska inkluderas. Varje gång ett paket läggs till en bunt, eller då rabattprocentsatsen ändras, måste alla parter godkänna att deras spel ska inkluderas i bunten innan den kan publiceras.`,
  _ = `Inbjuden via vänkod`,
  _ = `Synlighetsbegränsningar`,
  _ = `Det finns inga synlighetsbegränsningar orsakade av spelpris eller aktuell rabatt. `,
  _ = `Du kan behöva justera dina spelpriser i vissa valutor eller rabattnivån som tillämpas på bunten.`,
  _ = `Vill du kasta bort osparade ändringar?`,
  _ = `Instrumentpanel för reasidor`,
  _ = `Eventsidor för reakampanjer`,
  _ = `Här hittar du reasidorna på Steam som innehåller ett eller flera spel som du har administrationsrättigheter till. I vissa fall organiseras dessa sidor av eventarrangörer och ibland av Valve som en del av organiserade reakampanjer.`,
  _ = `Det här är alla aktiva och färdigställda reasidor skapade antingen av Valve eller en godkänd extern part. För att lägga till en ny partner som kan skapa sin egen reasida, %1$s. Du kan hänvisa din partner till %2$s.`,
  _ = `läs denna guide`,
  _ = `den externa dokumentationen om denna funktion`,
  _ = `Statistiköversikt`,
  _ = `Aktiva reor: %1$s`,
  _ = `Sidor för kommande säsongsrea: %1$s`,
  _ = `Dessa är de reasidor som vi planerar att ha med på Steams startsida under nästa stora säsongsrea (om de inkluderade spelen har en rabatt). Säkerställ att dessa inkluderar alla relevanta titlar i din franchise.`,
  _ = `Länkar`,
  _ = `Publicerade kommande reor: %1$s`,
  _ = `Utkast: %1$s`,
  _ = `Påbörjade reasidor (för närvarande dolda/opublicerade)`,
  _ = `Gamla utkast: %1$s`,
  _ = `Utkast som inte ändrats på över en månad`,
  _ = `Tidigare reor: %1$s`,
  _ = `Rean pågår från`,
  _ = `Rean pågår till`,
  _ = `Snabbsök bland inkluderade spel`,
  _ = `Detta är en lista över dina spel som är med i eventet.`,
  _ = `Sök`,
  _ = `Detta event är dolt och du har inte åtkomst till redigering. Men det har någon annan i ditt team. För att avgöra vilken person som har behörighet att redigera, hovra över gruppikonen och klicka på Se medlemslista. Som standard är det gruppmedlemmar med officerarstatus som har redigerarrättigheter för detta event.`,
  _ = `Detta event är inte synligt än, men vi visar det för dig eftersom du har ett spel som har listats på reasidan. Om detta är oväntat, kontakta arrangören av rean.`,
  _ = `Arrangör:`,
  _ = `Arrangörens kontaktinformation:`,
