  _ = `Varför ser jag detta?`,
  _ = `%1$s av dina appar har inkluderats på reasidan. Om du inte blev kontaktad angående deltagande i detta event, kontakta eventets arrangör.`,
  _ = `%1$s av dina appar har inkluderats på reasidan. Om du inte blev kontaktad angående deltagande i detta event, kontakta eventets arrangör.`,
