  _ = `Utelämna spelnamn från början av artiklar i paketets innehållslista.`,
  _ = `För att ta bort överflödig information och öka läsbarheten, utelämna spelnamnet plus blanksteg och karaktärer som kolon och bindestreck från början av artiklar såsom DLC och soundtrack när de listas i köpområdet för paket. Exempelvis visas Half-Life 2: Episode One som Episode One. Endast det exakta namnet på basspelet plus blanksteg och vanliga avgränsare som bindestreck och kolon är dolda.`,
