  _ = `Design: Bör innehålla din eventlogotyp över ett rutnät med dina mest populära spel, så att spelare lägger märke till spel som de känner till.`,
  _ = `Huvudkapsel för promoapp`,
  _ = `Användning: Bilden representerar ditt reaevent och används ibland när vi behöver presentera kampanjen på alternativa platser.`,
  _ = `Design: Bör innehålla din eventlogotyp över ett rutnät med dina mest populära spel, så att spelare lägger märke till spel som de känner till.`,
