  _ = `Använd uppladdningsverktyget nedan för att skicka in en förhandsvisning och säkerställa att din bild följer våra storleks- och urklippsmallar.`,
  _ = `Ladda upp förhandsvisning av takeover`,
  _ = `Använd uppladdningsverktyget nedan för att skicka in en förhandsvisning av både takeoverbannern och takeoverbannern för mobil för att säkerställa att bilden följer storleks- och urklippsmallarna.`,
  _ = `Ladda upp förhandsvisning av takeunderbannern`,
  _ = `Använd uppladdningsverktyget nedan för att skicka in en förhandsvisning av både takeunderbannern och takeunderbannern för mobil för att säkerställa att bilden följer storleks- och urklippsmallarna.`,
  _ = `Ladda upp förhandsvisning av bilder till reasidan`,
  _ = `Använd uppladdningsverktyget nedan för att skicka in förhandsvisningar av de fem elementen relaterade till reasidan och tillhörande lokalisering. Säkerställ att bilderna följer storleks- och urklippsmallarna.`,
  _ = `Särskilda instruktioner`,
  _ = `Ange eventuella särskilda instruktioner eller ytterligare information som din Steam-representant bör ha angående dina resurser. Inkluderar du exempelvis information om en tillhörande uppdatering? Finns det specifika varumärkesriktlinjer för en av dina resurser?`,
  _ = `särskild information om dina resurser`,
  _ = `Kontaktuppgifter`,
  _ = `Ange en eller flera e-postadresser till dem som du vill att vi kontaktar om vi har frågor eller feedback angående de uppladdade resurserna.`,
  _ = `Lista över e-postadresser separerade med komma`,
  _ = `Resurserna har skickats in!`,
  _ = `Steams kampanjteam kommer att granska resurserna och förbereda materialet till din kampanj. Vi hör av oss om vi behöver något mer.`,
