  _ = `Stort uppdateringstillkännagivande`,
  _ = `Vi behöver skapa ett nytt event av typen stor uppdatering, specifikt taggad för användning i det här marknadsföringsmeddelandet. <1>Läs också kraven.</1>`,
  _ = `Skapa nytt tillkännagivande`,
