  _ = `Skapa ett tillkännagivande om en stor uppdatering för användning i ett marknadsföringsmeddelande`,
  _ = `Läs och godkänn följande krav:`,
  _ = `Eventbeskrivningen ska vara noggrant skriven och beskriva uppdateringen. Varför är den viktig? Vilka stora ändringar ingår? Nämn också nya funktioner, uppdateringsanteckningar och liknande.`,
  _ = `Eventets titel ska vara fängslande, spännande och begriplig, även för inaktiva spelare.`,
  _ = `Huvudbilden ska tydligt visa själva uppdateringen och inte innehålla någon tilläggstext.`,
  _ = `Klicka här för att godkänna reglerna`,
