  _ = `Färg på karusellpil`,
  _ = `Om bakgrundsfärgen eller bakgrundsbilden är mycket ljus kan det göra pilen svår att se. Använd den här inställningen för att överskrida den vita standardfärgen på karusellpilarna.`,
  _ = `Om bakgrundsfärgen eller bakgrundsbilden är mycket ljus kan det göra pilen svår att se. Använd den här inställningen för att åsidosätta de vita och grå standardfärgerna på karusellens brödsmulor. Detta visas främst på mindre skärmar, inklusive Steam Deck.`,
