  _ = `Ange planerat utgivningsdatum`,
  _ = `Ändra planerat utgivningsdatum`,
  _ = `Tidigast möjliga utgivning: När ditt spels byggversion har verifierats.`,
  _ = `Tidigast möjliga utgivning: %1$s`,
  _ = `Ditt tidigaste möjliga utgivningsdatum är två veckor efter att din butikssida visats som ”Kommer snart” eller 21 dagar efter det första köpet av en appkredit, beroende på vilket som kommer sist. Planera i enlighet med detta.`,
  _ = `Ditt tidigaste möjliga utgivningsdatum är två veckor efter att din butikssida visats som ”Kommer snart”. Planera i enlighet med detta.`,
  _ = `Välj det datum du avser lansera din applikation på Steam. Uppskatta så gott du kan om det fortfarande är lång tid kvar. Om du behöver senarelägga din lansering måste du uppdatera datumet här minst två veckor innan det datum du tidigare uppgav.`,
  _ = `Det går inte att lansera under helgen, eftersom att Valve då inte kan hjälpa till med eventuella problem.`,
  _ = `Alla tider är i Pacific Time.`,
  _ = `Ditt planerade utgivningsdatum är för närvarande angett som ”%1$s”. Om du behöver göra ändringar, <1>kontakta Valve här</1> med anledningen till ditt nya utgivningsdatum och vilket datum du vill att det ska vara. Du bör vara rätt säker på att ditt nya datum är det datum då utgivningen kommer att ske.`,
  _ = `Obs: Eftersom din ”Kommer snart”-sida är aktiv, kommer en ändring av ditt utgivningsdatum att leda till att din butikssida publiceras omedelbart för att återspegla det uppdaterade datumet. Alla väntande ändringar av din butikssida blir då offentliga.`,
  _ = `Obs: Det tidigaste möjliga utgivningsdatumet du kan välja är %1$s. Du kommer att kunna trycka på knappen för utgivning när som helst efter detta datum, oavsett vad ditt planlagda datum är angett som.`,
  _ = `Redigera`,
  _ = `Avbryt`,
  _ = `Uppdatera`,
