  _ = `Planerat utgivningsdatum`,
  _ = `Offentligt datum`,
  _ = `Använd den här inställningen för att välja hur ditt datum ska visas i butiken.`,
  _ = `Om ett icke-specifikt format väljs, såsom ”månad år” eller ”år”, läggs spelet till sist på listan för den valda tidsperioden.`,
  _ = `Behöver du hjälp med utgivningsdatum? <1>Dokumentation</1> | <2>Steamworks-support</2>`,
