  _ = `Officiellt rabattevent`,
  _ = `Rabatt planerad`,
  _ = `Steg %1$s`,
  _ = `Allmänt inmatningsstöd`,
  _ = `För att bäst kunna beskriva spelets grad av kontrollstöd för spelare har vi en snabbguide med några få korta frågor. Gå igenom guiden och svara på frågorna så gott du kan, så att Steam kan hjälpa spelare att hitta spel som fungerar bra på deras enheter.`,
  _ = `Observera att alla VR-enheter som ditt spel stöder, inklusive inmatningsenheter, bör beskrivas i systemkraven. Kontrollstöd som beskrivs här bör hänvisa till stödet för skrivbords- eller Big Picture-läge.`,
  _ = `Vilka slags enheter kan användas för att spela ditt spel utan problem?`,
  _ = `Endast mus och tangentbord`,
  _ = `Mus och tangentbord, samt handkontroller`,
  _ = `Mus och tangentbord, men handkontroll föredras`,
  _ = `Handkontroll krävs – stöd för mus och tangentbord saknas`,
  _ = `Ja, spelet uppfyller ovanstående kriterier för fullt stöd.`,
  _ = `Nej, spelet uppfyller inte alla ovanstående kriterier.`,
  _ = `DUALSHOCK-kontroll (usb)`,
  _ = `DualShock-kontroll (USB + Bluetooth)`,
  _ = `DualSense-kontroll (usb)`,
  _ = `DualSense-kontroll (USB + Bluetooth)`,
  _ = `Nej, spelet har inte stöd för några PlayStation-kontroller.`,
  _ = `Ja, spelet har fullständig integration med Steam Input-API.`,
  _ = `Nej, spelet använder inte Steam Input-API.`,
  _ = `Stöd för Xbox-kontroller`,
  _ = `Om ditt spel har fullt stöd för Xbox-kontroller är det möjligt för en spelare att starta, konfigurera, spela och avsluta spelet utan tillgång till ett tangentbord. För att sanningsenligt indikera att spelet har fullt stöd för Xbox-kontroller ska man kunna göra följande:`,
  _ = `En spelare måste kunna göra allt i spelet med bara en handkontroll. Detta inkluderar att komma förbi eventuella startprogram, spela spelet, använda menyer, ändra inställningar och avsluta spelet.`,
  _ = `När handkontrollen är frånkopplad ska spelet pausas om det inte är ett flerspelarspel.`,
  _ = `Alla uppmaningar om att skriva in text ska öppna ett virtuellt tangentbord på skärmen.`,
  _ = `Om ditt spel stöder lokalt flerspelarläge måste läget fungera med flera handkontroller.`,
  _ = `Uppfyller ditt spel ovanstående kriterier för fullt stöd för Xbox-kontroller?`,
  _ = `Stöd för PlayStation-kontroller`,
  _ = `Om ditt spel har stöd för en eller flera av PlayStation-kontrollermodellerna som anges nedan, bör det i allmänhet vara möjligt att använda dessa enheter för att göra allt i spelet som kan göras med Xbox-kontroller. Dessutom måste ditt spel göra följande för att betraktas som PlayStation-kontroller med stöd:`,
  _ = `Visa rätt glyfer (symboler) på skärmen när användaren uppmanas att trycka på en specifik knapp på handkontrollen.`,
  _ = `Spela spelet, använda menyerna, ändra inställningar och avsluta.`,
  _ = `<1>USB-/Bluetooth-anmärkning:</1> Det kan vara vanligt att usb-anslutningen fungerar bra för PlayStation-kontroller på pc, men de kanske inte har samma slags stöd när de är anslutna via Bluetooth. Bekräfta med det tekniska teamet att spelet faktiskt fungerar med Bluetooth innan du väljer det nedan.`,
  _ = `<1>Ja</1>, spelet stöder: (välj alla som gäller)`,
  _ = `Integration med Steam Input-API`,
  _ = `Om ditt spel är helt integrerat med Steam Input API fungerar det fullt ut med nästan vilken som helst av 200+ modeller av handkontroller som en spelare kan ansluta, inklusive framtida modeller. För att sanningsenligt säga att ditt spel har detta stöd ska det åtminstone kunna göra följande:`,
  _ = `Implementera Steam Input API-handlingar och spåra den associerade handlingens ursprung för att visa rätt glyfer i spelet för de vanligaste handkontrollsmodellerna.`,
  _ = `Pausa automatiskt om handkontrollen är frånkopplad.`,
  _ = `Spelaren måste kunna mappa om knapparna på handkontrollen de använder via Steam-konfiguratorn.`,
  _ = `Om du är osäker, fråga ditt tekniska team om de använder Steam Input-API.`,
  _ = `Använder ditt spel Steam Input API:et till fullo enligt beskrivningen ovan?`,
