  _ = `Baserat på vad du har berättat för oss om kontrollstöd kommer Steam att visa följande översikt för kunder:`,
  _ = `Baserat på det du har berättat för oss om kontrollstöd kommer det inte visas något stöd för spelkontrollenheter på Steam.`,
