  _ = `Spelat och tillagt på önskelistan`,
  _ = `Inkluderar spel som spelare både spelade och lade till på önskelistan under eventet. Det räknas med här utöver att det räknas med i Totalt antal spelare och Totalt antal tillägg på önskelistor.`,
