  _ = `Besök på spelets butikssida via förfestivalssidan under eventet. Visas endast för spel där du kan se marknadsföringstrafik.`,
  _ = `Butiksbesök under festivalen`,
  _ = `Samtliga besök på spelets butikssida under eventet, från var som helst på Steam eller webben. Visas endast för spel där du kan se marknadsföringstrafik.`,
