  _ = `Se följande dokumentation om hantering av Steamworks-konto.`,
  _ = `Steams förfestival`,
  _ = `För mer information om Steams förfestival kan du läsa dokumentationen här:`,
  _ = `Dokumentation om Steams förfestival`,
  _ = `Du har inga spel som nyligen har deltagit i förfestivalen.`,
