  _ = `Dina spel:`,
  _ = `Mer från (franchisen/utvecklaren/utgivaren)`,
  _ = `Det finns inga skaparsidor för din app. Gå igenom dokumentationen om skaparsidor för <1>utvecklare/utgivare</1> eller <2>franchiser</2> för att upprätta dem för appen.`,
