  _ = `Spelinspelning – hantering av tidslinjeikon`,
  _ = `Ikoner som skapas här kan hänvisas till inifrån spelet för att markera specifika ögonblick på spelets inspelningstidslinje. Steam har också en standarduppsättning ikoner som du kan använda. Läs dokumentationen för mer information.`,
