  _ = `Unika identifierare på offentliga ikoner kan inte redigeras`,
  _ = `Färg`,
  _ = `ange unik identifierare ...`,
  _ = `Används av API-anrop (max %1$s tecken). Måste bestå av alfanumeriska gemener och vara minst tre tecken lång. Stöder även ”_” och ”-”. Mellanrum är inte tillåtna.`,
  _ = `Identifieraren innehåller tecken som inte stöds. Måste bestå av alfanumeriska gemener och vara minst tre tecken lång. Stöder även ”_” och ”-”. Mellanrum är inte tillåtna.`,
  _ = `Identifieraren kan inte börja med ordet steam_ som används för officiella ikoner.`,
