  _ = `Eftersom ikonerna är offentliga kan det hända att de refereras till någonstans, och därför kan de inte raderas eller döpas om. Du kan uppdatera bilden om så behövs.`,
  _ = `Skapa nya ikoner som ”offentliga” om du vill förbereda inför en offentlig lansering`,
  _ = `Dolda ikoner`,
  _ = `Använd dolda ikoner för att testa dem innan du synliggör dem. Använd uppsättningarna nedan för att koppla specifika ikoner till specifika byggversionsgrenar om du behöver begränsa åtkomsten.`,
