  _ = `Kopiering av tidslinjemarkören lyckades. `,
  _ = `Du kan även välja en eller flera grenar att associera elementen med. Alla spelare som kör de valda grenarna kommer att kunna se resurserna. Om någon gren som inte är skyddad av ett lösenord väljs, behandlar vi ikonerna som offentligt synliga.`,
